-- Maison Academy · new cards: tmp_0013a (15 cards, unit "Suggestive selling")
-- Generated by scripts/make_new_cards_sql.py from content/drafts/selling-suggestive-cards.json. All arrive in review.
insert into public.units (id, track_id, name, sort) values ('suggestive-selling', 'suggestive', 'Suggestive selling', 1)
on conflict (id) do nothing;

insert into public.cards (id, track_id, unit_id, level, roles, type, prompt, options, answer, explanation,
  why_it_matters, is_allergen, source_ref, review_note, status, updated_by)
values
  ('sug-suggestive-selling-0001', 'suggestive', 'suggestive-selling', 2, array['server','bar','host']::text[], 'mcq', 'What is suggestive selling?', '["Recommending a better version of what they''ve already ordered", "Recommending the most expensive dish on the menu", "Recommending today''s special to every table", "Recommending items the guest hadn''t planned to order"]'::jsonb, '["Recommending items the guest hadn''t planned to order"]'::jsonb, 'Suggestive selling recommends additional items the guest hadn''t planned to order, to add to what they''re already having. Upselling is upgrading what they''ve chosen.', 'Knowing the difference helps you pick the right technique at the right moment.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 2.1', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-suggestive-selling-0002', 'suggestive', 'suggestive-selling', 2, array['server','bar','host']::text[], 'mcq', 'Suggestive selling mainly increases which part of the check?', '["The number of guests", "The size of each portion", "The value of each item", "The number of items"]'::jsonb, '["The number of items"]'::jsonb, 'Suggestive selling adds more things; upselling makes each thing better.', 'A simple way to remember which technique you''re using.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 2.2', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-suggestive-selling-0003', 'suggestive', 'suggestive-selling', 2, array['server','bar','host']::text[], 'multi', 'Which of these are suggestive selling? Pick all that apply.', '["Suggesting Patatas Bravas to share while they decide", "Offering the Black Angus Tenderloin instead of the Steak and Fries", "Offering an espresso after dessert", "Suggesting a large bottle of water for the table", "Offering Hendrick''s in the guest''s gin and tonic"]'::jsonb, '["Suggesting Patatas Bravas to share while they decide", "Offering an espresso after dessert", "Suggesting a large bottle of water for the table"]'::jsonb, 'Starters, waters and coffee are new items on the check, so they''re suggestive selling. A premium gin or a better steak upgrades something already ordered, so that''s upselling.', 'Each technique has its own best moment in the meal.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), sections 2.2 and 9.1', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-suggestive-selling-0004', 'suggestive', 'suggestive-selling', 2, array['server']::text[], 'order', 'Put these suggestions in the order they come during a meal.', '["A signature drink at the greeting", "A sharing starter as you present the menu", "A dessert as you clear the mains", "A side dish with the main order", "Coffee or tea after dessert", "A second round at the mid-meal check-in"]'::jsonb, '["A signature drink at the greeting", "A sharing starter as you present the menu", "A side dish with the main order", "A second round at the mid-meal check-in", "A dessert as you clear the mains", "Coffee or tea after dessert"]'::jsonb, 'Greeting: drinks. Menu: starters to share. Mains: sides. Mid-meal: another round. Clearing mains: dessert. After dessert: coffee or tea.', 'Suggesting an item just before the guest would think of it is what makes it welcome.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 3.1', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-suggestive-selling-0005', 'suggestive', 'suggestive-selling', 2, array['server']::text[], 'mcq', 'You''re clearing the mains. Which suggestion fits this moment best?', '["Another round of the same drinks", "A sharing starter", "A coffee or mint tea", "A dessert, named and described"]'::jsonb, '["A dessert, named and described"]'::jsonb, 'Clearing the mains is the moment for dessert. Coffee, tea and digestifs come after dessert.', 'The right suggestion at the right moment feels like good service, not selling.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 3.1', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-suggestive-selling-0006', 'suggestive', 'suggestive-selling', 2, array['server','bar','host']::text[], 'mcq', 'Which is the strongest starter suggestion?', '["\"Our starters are all really good, any you like the look of?\"", "\"Have you tried our Van Tricht croquettes? Crispy, with an aged gouda inside.\"", "\"Would anyone like to have a look at our starters before you choose your mains tonight?\"", "\"Would anyone like a starter tonight, or straight to mains?\""]'::jsonb, '["\"Have you tried our Van Tricht croquettes? Crispy, with an aged gouda inside.\""]'::jsonb, 'Name a specific item and describe one or two qualities. Vague questions get vague answers, usually "no".', 'A specific dish creates a picture in the guest''s mind.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 3.2', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-suggestive-selling-0007', 'suggestive', 'suggestive-selling', 2, array['server']::text[], 'mcq', 'Which dessert question works best?', '["\"Will it be dessert, or just the bill for you?\"", "\"Do you want any dessert tonight?\"", "\"Would you like the Dame Blanche or the Tarte Tatin to finish?\"", "\"You really should have a dessert tonight, they''re all really great.\""]'::jsonb, '["\"Would you like the Dame Blanche or the Tarte Tatin to finish?\""]'::jsonb, 'Offer a choice, not a yes/no question: it invites the guest to choose rather than refuse.', '"Which would you prefer?" is easier to answer than "Do you want...?"', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 3.2', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-suggestive-selling-0008', 'suggestive', 'suggestive-selling', 2, array['server','bar','host']::text[], 'mcq', 'Why suggest a starter for the table to share, rather than one each?', '["It''s quicker to write on the pad", "Sharing feels like less of a commitment", "Guests always want to try each other''s food", "The kitchen prefers to cook sharing plates"]'::jsonb, '["Sharing feels like less of a commitment"]'::jsonb, 'Sharing items feel lower-commitment, so "Shall I bring one to share?" is easier to say yes to than asking each guest.', 'Guests say yes more easily when it doesn''t feel like a big decision.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 3.2', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-suggestive-selling-0009', 'suggestive', 'suggestive-selling', 2, array['server','bar','host']::text[], 'mcq', 'What makes a personal recommendation work?', '["You''ve tasted it and genuinely like it", "It''s the dish the team needs to sell most", "It''s the most expensive dish on the menu", "It''s on promotion this week"]'::jsonb, '["You''ve tasted it and genuinely like it"]'::jsonb, 'Only recommend things you''ve tasted and genuinely like. Guests can tell when enthusiasm isn''t genuine.', 'Guests trust honest, personal opinions.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), sections 3.2 and 7', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-suggestive-selling-0010', 'suggestive', 'suggestive-selling', 2, array['server','bar','host']::text[], 'mcq', 'Which words help a guest imagine how a dish tastes?', '["Nice, good, tasty", "Crispy, slow-cooked, house-made", "Popular, classic, best-selling", "Large portions, filling, great value"]'::jsonb, '["Crispy, slow-cooked, house-made"]'::jsonb, 'Sensory words like crispy, slow-cooked, chargrilled and house-made help guests imagine the taste. Describe one or two qualities, not the full recipe.', 'A dish the guest can picture is a dish they want.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 3.2', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-suggestive-selling-0011', 'suggestive', 'suggestive-selling', 2, array['server','bar','host']::text[], 'mcq', 'Which phrase should you avoid when taking an order?', '["\"Is that all?\"", "\"It pairs beautifully with...\"", "\"Have you tried our...?\"", "\"My personal favourite is...\""]'::jsonb, '["\"Is that all?\""]'::jsonb, 'Avoid closed phrases like "Is that all?" or "Do you want anything else?". Use specific, inviting ones like "Have you tried our...?"', 'A closed question invites a "yes, that''s all".', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 6', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-suggestive-selling-0012', 'suggestive', 'suggestive-selling', 2, array['server']::text[], 'scenario', 'A guest politely declines dessert. What do you do?', '["Ask \"Are you sure?\" in case they change their mind", "Accept it, and offer coffee or mint tea just once", "Leave the dessert menu on the table, just in case", "Describe the desserts again in more detail"]'::jsonb, '["Accept it, and offer coffee or mint tea just once"]'::jsonb, 'Accept a no graciously and offer a lighter alternative only once. Repeating a suggestion after a no damages trust.', 'A guest who feels respected comes back.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), sections 7 and 9.2', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-suggestive-selling-0013', 'suggestive', 'suggestive-selling', 2, array['server','bar','host']::text[], 'mcq', 'How many items should you recommend at once?', '["One or two", "A whole section of the menu", "Every special of the day", "Three or four"]'::jsonb, '["One or two"]'::jsonb, 'Too many options overwhelm guests. Recommend one or two items.', 'A clear recommendation is easier to say yes to.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 7', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-suggestive-selling-0014', 'suggestive', 'suggestive-selling', 2, array['server']::text[], 'mcq', 'When is it too late to suggest a starter?', '["Once the mains have been ordered", "When you greet the table", "While you take the table''s drinks order", "While the guests read the menu"]'::jsonb, '["Once the mains have been ordered"]'::jsonb, 'Timing matters: offering starters after the mains are ordered, or dessert while guests are still eating, comes too late or too early.', 'Suggestions only work when they fit the flow of the meal.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 7', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-suggestive-selling-0015', 'suggestive', 'suggestive-selling', 2, array['server','bar','host']::text[], 'mcq', 'Of the five habits of a great seller, which means "suggest once, respect the answer"?', '["Time", "Read", "Respect", "Describe"]'::jsonb, '["Respect"]'::jsonb, 'The five habits are Taste, Read, Describe, Time and Respect. Respect means suggest once, respect the answer, and always put the guest first.', 'A guest who feels looked after will return; one who feels pushed won''t.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 10', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)')
on conflict (id) do nothing;

update public.card_versions set saved_by = 'Claude (draft for David)' where saved_by = 'System';
update public.audit_log set actor = 'Claude (draft for David)' where actor = 'System' and action = 'card_created';

-- Maison Academy · new cards: tmp_0013b (11 cards, unit "Reading the guest")
-- Generated by scripts/make_new_cards_sql.py from content/drafts/selling-reading-guest-cards.json. All arrive in review.
insert into public.units (id, track_id, name, sort) values ('reading-the-guest', 'suggestive', 'Reading the guest', 2)
on conflict (id) do nothing;

insert into public.cards (id, track_id, unit_id, level, roles, type, prompt, options, answer, explanation,
  why_it_matters, is_allergen, source_ref, review_note, status, updated_by)
values
  ('sug-reading-the-guest-0001', 'suggestive', 'reading-the-guest', 2, array['server','bar','host']::text[], 'scenario', 'A couple tells you it''s their anniversary. How do you adjust your suggestions?', '["Keep suggestions quick and practical", "Explain the signature dishes", "Suggest value options and sharing items for the table", "Suggest a bottle, and a dessert to share"]'::jsonb, '["Suggest a bottle, and a dessert to share"]'::jsonb, 'Celebrating guests are open to treating themselves: suggest bottles, premium items, desserts to share and a celebration touch.', 'The right suggestion makes their occasion feel special.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 5', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-reading-the-guest-0002', 'suggestive', 'reading-the-guest', 2, array['server','bar','host']::text[], 'scenario', 'Two guests at a business lunch keep checking their watches. How do you adjust?', '["Suggest a sharing starter while they decide", "Keep suggestions quick; offer coffee to go", "Suggest a bottle and a dessert to share", "Explain the signature dishes in detail"]'::jsonb, '["Keep suggestions quick; offer coffee to go"]'::jsonb, 'Guests checking their watches are short on time, so keep suggestions quick and practical, and offer coffee to go.', 'Respecting their time is the best service you can give.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 5', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-reading-the-guest-0003', 'suggestive', 'reading-the-guest', 2, array['server','bar','host']::text[], 'scenario', 'A family is reading the prices very carefully. How do you adjust?', '["Suggest value options and sharing items", "Suggest premium upgrades as a little treat for them", "Don''t suggest anything at all", "Suggest the specials of the day"]'::jsonb, '["Suggest value options and sharing items"]'::jsonb, 'Budget-conscious guests: recommend value options and sharing items, and avoid pushing premium upgrades.', 'Guests who feel their budget is respected relax and enjoy their visit.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 5', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-reading-the-guest-0004', 'suggestive', 'reading-the-guest', 2, array['server','bar','host']::text[], 'scenario', 'Guests tell you it''s their first time at Maison Mathis. What fits best?', '["Mention the new dishes and what''s changed since last month", "Explain our signature dishes and house specialities", "Leave them to explore the menu alone", "Suggest the quickest dishes"]'::jsonb, '["Explain our signature dishes and house specialities"]'::jsonb, 'First-time visitors are curious and want guidance, so explain the signature dishes and house specialities.', 'A great first visit is how a guest becomes a regular.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 5', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-reading-the-guest-0005', 'suggestive', 'reading-the-guest', 2, array['server','bar','host']::text[], 'mcq', 'A guest isn''t drinking alcohol. What do you do with drinks suggestions?', '["Suggest mocktails and fresh juices as warmly as cocktails", "Ask them why they''re not drinking tonight", "Offer water only", "Skip drinks suggestions altogether so they don''t feel awkward"]'::jsonb, '["Suggest mocktails and fresh juices as warmly as cocktails"]'::jsonb, 'Guests not drinking alcohol still want something special. Recommend mocktails, fresh juices and premium waters with the same enthusiasm, and never make a guest explain.', 'Every guest deserves a great drink, with or without alcohol.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), sections 5 and 7', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-reading-the-guest-0006', 'suggestive', 'reading-the-guest', 2, array['server','bar','host']::text[], 'mcq', 'Regulars know the menu well. What should you suggest to them?', '["The signature dishes, explained in full detail again", "The most expensive dish on the menu", "Nothing; they already know what they want", "New items and specials, and their favourites"]'::jsonb, '["New items and specials, and their favourites"]'::jsonb, 'Regulars know the menu, so mention new items and specials, and remember their favourites.', 'Remembering a regular''s favourite makes them feel at home.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 5', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-reading-the-guest-0007', 'suggestive', 'reading-the-guest', 2, array['server','bar','host']::text[], 'mcq', 'What''s the golden rule of selling?', '["Sell to the guest''s needs, not to your target", "Focus on the items with the best margin", "Suggest something on every visit to the table", "Always offer the premium option first"]'::jsonb, '["Sell to the guest''s needs, not to your target"]'::jsonb, 'Sell to the guest''s needs, not to your target. A guest who feels looked after will return; a guest who feels pushed will not.', 'Long-term, loyal guests are worth far more than one bigger check.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 5', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-reading-the-guest-0008', 'suggestive', 'reading-the-guest', 2, array['server','bar']::text[], 'scenario', 'A guest is showing signs of having had too much to drink. Their glass is empty. What do you do?', '["Suggest a lighter beer, like Hoegaarden", "Offer a smaller measure or a lighter drink instead of a full one", "Ask if they''d like the same again", "Don''t suggest another drink; follow responsible service rules"]'::jsonb, '["Don''t suggest another drink; follow responsible service rules"]'::jsonb, 'Never suggest another round to a guest showing signs of intoxication. Follow responsible service rules and the venue''s licensing conditions.', 'Guest safety and our licence come before any sale.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 7', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-reading-the-guest-0009', 'suggestive', 'reading-the-guest', 2, array['server']::text[], 'scenario', 'A guest with a nut allergy asks which dessert you''d recommend. What do you do?', '["Say you can''t recommend any desserts", "Recommend a dessert that has no nuts listed anywhere on the menu", "Recommend the Dame Blanche straight away", "Confirm with the kitchen first, then recommend a safe option"]'::jsonb, '["Confirm with the kitchen first, then recommend a safe option"]'::jsonb, 'Always check allergies before recommending and confirm with the kitchen if you''re unsure. Never guess, then recommend a safe option with genuine enthusiasm.', 'An allergy can be life-threatening, and the menu doesn''t show every ingredient.', true, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), sections 7 and 9.2', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality). Allergen card: needs the kitchen check.', 'review', 'Claude (draft for David)'),
  ('sug-reading-the-guest-0010', 'suggestive', 'reading-the-guest', 2, array['server','bar','host']::text[], 'mcq', 'Which tables should you offer upgrades to?', '["Only the tables that look like they''re big spenders", "Only tables that are celebrating", "Any table, respectfully, without assuming", "Only regulars who know the menu"]'::jsonb, '["Any table, respectfully, without assuming"]'::jsonb, 'Never assume who can or can''t afford an upgrade. Offer options respectfully to every table.', 'Judging a guest''s budget is the quickest way to lose their trust.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 7', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('sug-reading-the-guest-0011', 'suggestive', 'reading-the-guest', 2, array['server','bar','host']::text[], 'mcq', 'Before service, what should you check with the kitchen so you don''t sell the unavailable?', '["The chef''s favourite dish", "Sold-out (86''d) items and preparation times", "Tonight''s table plan and the reservations list", "The staff meal time"]'::jsonb, '["Sold-out (86''d) items and preparation times"]'::jsonb, 'Check with the kitchen before service for 86''d (sold-out) items and preparation times.', 'Recommending a dish that''s sold out disappoints the guest twice.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 7', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)')
on conflict (id) do nothing;

update public.card_versions set saved_by = 'Claude (draft for David)' where saved_by = 'System';
update public.audit_log set actor = 'Claude (draft for David)' where actor = 'System' and action = 'card_created';

-- Maison Academy · new cards: tmp_0013c (14 cards, unit "Upselling")
-- Generated by scripts/make_new_cards_sql.py from content/drafts/selling-upselling-cards.json. All arrive in review.
insert into public.units (id, track_id, name, sort) values ('upselling', 'upselling', 'Upselling', 1)
on conflict (id) do nothing;

insert into public.cards (id, track_id, unit_id, level, roles, type, prompt, options, answer, explanation,
  why_it_matters, is_allergen, source_ref, review_note, status, updated_by)
values
  ('up-upselling-0001', 'upselling', 'upselling', 2, array['server','bar','host']::text[], 'mcq', 'What is upselling?', '["Suggesting a higher-value version of what the guest is ordering", "Adding a service charge for premium items", "Suggesting the most expensive item to every guest", "Suggesting an extra item that the guest hadn''t planned to order"]'::jsonb, '["Suggesting a higher-value version of what the guest is ordering"]'::jsonb, 'Upselling encourages a higher-value version of something already being ordered: a premium brand, larger size, better cut or an add-on.', 'Upselling raises the value of each item, not the number of items.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 2.1', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('up-upselling-0002', 'upselling', 'upselling', 2, array['server','bar','host']::text[], 'mcq', 'Which question is typical of upselling?', '["\"Would you like to add...?\"", "\"Can I get you anything else with that?\"", "\"Would you prefer the... instead?\"", "\"Is that everything for you?\""]'::jsonb, '["\"Would you prefer the... instead?\""]'::jsonb, 'Upselling asks "Would you prefer the... instead?"; suggestive selling asks "Would you like to add...?"', 'The question shows which technique you''re using.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), sections 2.2 and 10', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('up-upselling-0003', 'upselling', 'upselling', 2, array['server','bar','host']::text[], 'multi', 'Which of these are upselling? Pick all that apply.', '["Guest orders a gin and tonic; you offer it with Hendrick''s", "Guest orders mains only; you suggest Patatas Bravas to share", "Guest orders the Steak and Fries; you offer the Black Angus Tenderloin instead", "Mains are cleared; you suggest the Dame Blanche", "Guest orders the Signature Burger; you suggest adding pork bacon"]'::jsonb, '["Guest orders the Steak and Fries; you offer the Black Angus Tenderloin instead", "Guest orders a gin and tonic; you offer it with Hendrick''s", "Guest orders the Signature Burger; you suggest adding pork bacon"]'::jsonb, 'A better cut, a premium gin and an add-on all raise the value of something the guest already chose. A new starter or dessert is suggestive selling.', 'Knowing which is which helps you choose the right moment for each.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), sections 2.3, 4.1 and 9.1', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('up-upselling-0004', 'upselling', 'upselling', 2, array['server','bar','host']::text[], 'mcq', 'You suggest adding cheddar (AED 5) to a guest''s Veggie Burger. Which technique is that?', '["Both at the same time", "Neither; it''s a substitution", "Suggestive selling", "Upselling (an add-on)"]'::jsonb, '["Upselling (an add-on)"]'::jsonb, 'Add-ons to an item the guest already chose, like extra cheese on a burger, count as upselling because they raise that item''s value.', 'Add-ons are the easiest upsell: the guest has already said yes to the dish.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), sections 2.3 note and 9.1', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('up-upselling-0005', 'upselling', 'upselling', 2, array['server','bar','host']::text[], 'mcq', 'When is the best moment to upsell?', '["After the order is in the POS", "At the check back", "The moment the guest names the item", "When you bring the food to the table"]'::jsonb, '["The moment the guest names the item"]'::jsonb, 'Upsell right when the guest names the item. Once the order is placed and you''ve walked away, the moment has gone.', 'An upgrade offered later means changing an order, which guests rarely do.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 4.2', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('up-upselling-0006', 'upselling', 'upselling', 2, array['server','bar','host']::text[], 'mcq', 'A guest orders a glass of wine at AED 45. Which upgrade are they most likely to accept?', '["One at about AED 100", "One at about AED 150", "One at about AED 60", "The most expensive bottle"]'::jsonb, '["One at about AED 60"]'::jsonb, 'Offer one step up, not three. A guest ordering a AED 45 glass is more likely to accept a AED 60 option than a AED 150 one.', 'A small step feels like a treat; a big jump feels like pressure.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 4.2', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('up-upselling-0007', 'upselling', 'upselling', 2, array['server','bar','host']::text[], 'mcq', 'An upgrade carries a supplement. When do you mention the price?', '["After they''ve agreed to it", "Only if the guest asks", "Not at all; it shows on the bill", "Naturally, as you suggest it"]'::jsonb, '["Naturally, as you suggest it"]'::jsonb, 'Be transparent: mention a supplement naturally when you suggest the upgrade, so the guest is never surprised by the bill.', 'A surprise on the bill turns a good meal into a complaint.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), sections 4.2 and 7', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('up-upselling-0008', 'upselling', 'upselling', 2, array['server']::text[], 'mcq', 'Which steak upsell is strongest?', '["\"The Wagyu is our most expensive steak, if you like.\"", "\"Would you like the more expensive steak instead?\"", "\"For something special, the Westholme Wagyu is beautifully marbled; it''s AED 130 more.\"", "\"Most of our guests go for the Wagyu striploin these days; it''s a very popular choice.\""]'::jsonb, '["\"For something special, the Westholme Wagyu is beautifully marbled; it''s AED 130 more.\""]'::jsonb, 'Explain the benefit to the guest, not just the price, and be clear about the supplement. The Wagyu striploin is AED 265; the Steak and Fries is AED 135.', 'Guests upgrade when they understand what they''ll get.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 4.2', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('up-upselling-0009', 'upselling', 'upselling', 2, array['server']::text[], 'mcq', 'A guest orders the Steak and Fries 200 gr (AED 135). What''s the natural one-step upsell?', '["The Black Angus Tenderloin 220 gr (AED 209)", "The Belgian Steak Tartare (AED 135)", "The Grilled Wagyu Striploin 250 gr (AED 265)", "A second Steak and Fries to share"]'::jsonb, '["The Black Angus Tenderloin 220 gr (AED 209)"]'::jsonb, 'Offer the next level up, not the most expensive: from the Steak and Fries, that''s the Black Angus Tenderloin.', 'One step up feels like a natural treat, not a hard sell.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 4.1', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('up-upselling-0010', 'upselling', 'upselling', 2, array['server','bar']::text[], 'scenario', 'Two guests each order a glass of the same white wine and mention a second round. What do you suggest?', '["A cocktail for the second round", "Two glasses now, and you''ll check back later for the next", "A glass of Champagne each instead", "A bottle: better value, kept chilled at the table"]'::jsonb, '["A bottle: better value, kept chilled at the table"]'::jsonb, 'If guests plan a second glass each, a bottle works out better value and stays chilled at the table.', 'The guest gets better value and you save a trip to the bar.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), sections 2.3 and 4.1', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('up-upselling-0011', 'upselling', 'upselling', 2, array['server','bar','host']::text[], 'mcq', 'Why does a pairing make an upsell easier?', '["It feels like expert advice, not a sales pitch", "It speeds up the order", "The kitchen prefers dishes in pairs", "It always works out cheaper for the guest in the end"]'::jsonb, '["It feels like expert advice, not a sales pitch"]'::jsonb, 'Pairing an upgrade with something the guest already ordered makes it feel like expert advice rather than a sales pitch.', 'Guests welcome advice; they resist being sold to.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 4.2', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('up-upselling-0012', 'upselling', 'upselling', 2, array['server','barista']::text[], 'mcq', 'A guest orders a latte. Which suggestion is an upsell?', '["A second latte later", "Adding an extra shot", "A glass of water", "A croissant to go with it"]'::jsonb, '["Adding an extra shot"]'::jsonb, 'An extra shot upgrades the latte the guest already chose, so it''s upselling. A croissant is a new item, so it''s suggestive selling.', 'Small coffee upgrades add up over a busy morning.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 4.1', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('up-upselling-0013', 'upselling', 'upselling', 2, array['server','bar','host']::text[], 'mcq', 'What''s the main risk of overdoing upselling?', '["The guest feels judged on budget or misled on price", "The kitchen runs out of premium items", "The bill takes longer to print", "The guest feels pushed into ordering far too much food"]'::jsonb, '["The guest feels judged on budget or misled on price"]'::jsonb, 'Overdone upselling leaves guests feeling judged on budget or misled on price. Overdone suggestive selling makes them feel pushed into ordering too much.', 'Trust is harder to win back than a sale.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 2.2', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)'),
  ('up-upselling-0014', 'upselling', 'upselling', 2, array['server']::text[], 'scenario', 'An anniversary couple orders two glasses of house wine. What''s the best approach?', '["Suggest a bottle now, and a dessert to share later", "Suggest a bottle, a starter and the Wagyu at once", "Suggest the most expensive Champagne straight away", "Serve the glasses and leave them to it"]'::jsonb, '["Suggest a bottle now, and a dessert to share later"]'::jsonb, 'Upsell the wine to a bottle at the moment they order, and suggest a shared dessert when the mains are cleared.', 'Well-timed suggestions make the occasion feel special without pressure.', false, 'Server Training Guide: Sales Techniques (David, SWR Hospitality), section 9.2', 'Drafted by Claude 2026-10-20 from Server Training Guide: Sales Techniques (David, SWR Hospitality).', 'review', 'Claude (draft for David)')
on conflict (id) do nothing;

update public.card_versions set saved_by = 'Claude (draft for David)' where saved_by = 'System';
update public.audit_log set actor = 'Claude (draft for David)' where actor = 'System' and action = 'card_created';

select string_agg(unit_id || ': ' || n, ', ') as added from (select unit_id, count(*) n from public.cards where unit_id in ('suggestive-selling','reading-the-guest','upselling') group by unit_id order by unit_id) s;
